from unittest import mock
from ute_common_abstract_core.config import Config as CoreConfig
from ...lteuepool import CfgFileBasedUePool
from .demo_uegroup import DemoUeGroup
from ...exceptions import RequiredUeNotFound, NotEnoughRequiredUes


class DemoUePool(CfgFileBasedUePool):
    """Demo Ue Pool"""
    def _has_matching_characteristics(self, ue_config, ue_characteristics):
        # base class checks:
        # - matching tags inside 'CAPABILITIES' config key
        # - matching 'STARTING_CELL' config key
        if super()._has_matching_characteristics(ue_config, ue_characteristics):
            if ue_characteristics.ue_capabilities is None:
                return True
            # matching value inside 'UE_CAPABILITIES' config key
            matching = self._matching_ue_capabilities(ue_config, ue_characteristics.ue_capabilities)
            return matching
        return False

    def _matching_ue_capabilities(self, ue_config, ue_capabilities):
        matching = False
        if ('UE_CAPABILITIES' in ue_config) and ('hex' in ue_config['UE_CAPABILITIES']):
            if ue_capabilities.hex:  # DemoUe supports only check-by-hex uecap
                matching = ue_capabilities.hex == ue_config['UE_CAPABILITIES']['hex']
        return matching

    def get_ue_group(self, ue_characteristics, ues_number):
        """
        Return UE-group instance fulfilling requirements.

        :param ue_characteristics: requirements for UE
        :param ues_number: needed number of UEs with such requirements
        :return: ue group instance
        :raises: :py:class:`ute_ue.exceptions.NotEnoughRequiredUes`: If not enough matching ues found
        """
        from ute_common_abstract_core.device.demo.demo_device import DemoDevice

        def _create_ue_holder(self, device_name, device_config):
            """Create UE that is not derived from LteUe but just works as UE-placeholder"""
            return DemoDevice(device_name, device_config)

        # find ues and build LteUeGroup without building list of LteUe
        taken_ues = []
        with mock.patch.object(self.__class__, 'create_device', _create_ue_holder):
            try:
                for idx in range(ues_number):
                    found_ue = self.get_ue(ue_characteristics)  # will withdraw UE from available-UEs
                    taken_ues.append(found_ue)
            except RequiredUeNotFound:
                # release already got ues to let them be available in pool
                for ue in taken_ues:
                    self.release_ue(ue)
                raise NotEnoughRequiredUes(required_ue_number=ues_number,
                                           current_ue_number=len(taken_ues),
                                           device_characteristics=ue_characteristics)
            else:
                ue_group = DemoUeGroup(ues=taken_ues)
                return ue_group

    def release_ue_group(self, ue_group):
        """
        Release UEs contained in UE-group into uepool.

        :param ue_group: UE-group instance
        :return: None
        """
        for ue in ue_group.ues:
            self.release_ue(ue)

    def create_device(self, device_name, device_config):
        """
        Create instance of device

        :param device_name:
        :param device_config:
        :return: device instance

        UE-pool should populate created UEs with PDN configuration
        specific for given UE-pool-type

        +---------------------------------------------------------+
        |     Example  YAML configuration                         |
        +=========================================================+
        |                                                         |
        | ::                                                      |
        |                                                         |
        |   PDN:                                                  |
        |       default:                                          |
        |           DemoUePool:                                   |
        |               apn: wap.nokia.com                        |
        |               pdp_type: IPV4V6                          |
        |           OtherUePool:                                  |
        |               pdn_param_x: x_value_1                    |
        |       emergency:                                        |
        |           DemoUePool:                                   |
        |               apn: wap2.nokia.com                       |
        |               pdp_type: Ethernet                        |
        |           OtherUePool:                                  |
        |               pdn_param_x: x_value_2                    |
        |                                                         |
        +---------------------------------------------------------+

        DemoUePool should extract only data that belongs to it.

        +---------------------------------------------------------+
        |     Extracted configuration data passed to DemoUe       |
        +=========================================================+
        |                                                         |
        | ::                                                      |
        |                                                         |
        |   {'PDN': {                                             |
        |       'default': {                                      |
        |           'apn': 'wap.nokia.com',                       |
        |           'pdp_type': 'IPV4V6'                          |
        |       },                                                |
        |       'emergency': {                                    |
        |           'apn': 'wap2.nokia.com',                      |
        |           'pdp_type': 'Ethernet'                        |
        |       },                                                |
        |   }                                                     |
        |                                                         |
        +---------------------------------------------------------+

        UE-pool should populate created UEs with APP_SERVERS configuration
        that is required for data traffic

        +---------------------------------------------------------+
        |     Example  YAML configuration                         |
        +=========================================================+
        |                                                         |
        | ::                                                      |
        |                                                         |
        |   APP_SERVERS                                           |
        |       APPSERVER0:                                       |
        |           host: APP_SVR                                 |
        |           bind_interface_ip: 192.168.44.130             |
        |       APPSERVER0_via_PGW_1:                             |
        |           host: APP_SVR_via_SGW                         |
        |           bind_interface_ip: 192.168.44.130             |
        |           sudo_password: passwd                         |
        |           iperf:                                        |
        |               path: /usr/bin/                           |
        |               use_sudo_when: "port<1200"                |
        |                                                         |
        +---------------------------------------------------------+

        """
        demo_ue_pdn_config = self._extract_pdn_config()
        if demo_ue_pdn_config:
            device_config['CONSTRUCTOR_PARAMETERS']['configuration']['PDN'] = demo_ue_pdn_config
        app_servers_config = self._extract_app_servers_config()
        if app_servers_config:
            if 'data_transfer' not in device_config['CONSTRUCTOR_PARAMETERS']['configuration']:
                device_config['CONSTRUCTOR_PARAMETERS']['configuration']['data_transfer'] = {}
            device_config['CONSTRUCTOR_PARAMETERS']['configuration']['data_transfer']['APP_SERVERS'] = app_servers_config
        ver = self._extract_config_version()
        if ver:
            if 'data_transfer' not in device_config['CONSTRUCTOR_PARAMETERS']['configuration']:
                device_config['CONSTRUCTOR_PARAMETERS']['configuration']['data_transfer'] = {}
            device_config['CONSTRUCTOR_PARAMETERS']['configuration']['data_transfer']['VERSION'] = ver
        device = super().create_device(device_name, device_config)
        return device

    def _extract_pdn_config(self):
        demo_ue_pdn_config = {}
        # pdn_config = CoreConfig().get_config(section='PDN')
        pdn_config = None
        whole_config = CoreConfig().get_config()
        if whole_config and ('PDN' in whole_config):
            pdn_config = whole_config['PDN']
        if pdn_config:
            ue_pool_name = self.__class__.__name__
            for pdn_name, pdn_cfg_per_ue_pool in pdn_config.items():
                demo_ue_pdn_config[pdn_name] = {'apn': pdn_cfg_per_ue_pool['apn']}  # apn is required key
                if ue_pool_name in pdn_cfg_per_ue_pool:
                    demo_ue_pdn_config[pdn_name].update(pdn_cfg_per_ue_pool[ue_pool_name])
        return demo_ue_pdn_config

    @staticmethod
    def _extract_app_servers_config():
        # app_servers_config = CoreConfig().get_config(section='APP_SERVERS')
        app_servers_config = None
        whole_config = CoreConfig().get_config()
        if whole_config and ('APP_SERVERS' in whole_config):
            app_servers_config = whole_config['APP_SERVERS']
        return app_servers_config

    @staticmethod
    def _extract_config_version():
        ver = None
        whole_config = CoreConfig().get_config()
        if whole_config and ('VERSION' in whole_config):
            ver = whole_config['VERSION']
        return ver
